#!/usr/bin/env python3
"""Generate the docs page from core's compiled canonical input defaults."""
import argparse,hashlib,json,pathlib
root=pathlib.Path(__file__).resolve().parents[1]
parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');parser.add_argument('--core',default=str(root.parent/'core'),help='core checkout (default: ../core)');args=parser.parse_args()
source=pathlib.Path(args.core)/'config/input.default.json';data=source.read_bytes();config=json.loads(data)
lines=['---','title: Keymap','description: Hyprune keymap v3 defaults, generated from the core config.','---','','<!-- Generated by scripts/generate-keymap.py; edit core/config/input.default.json. -->',f'<!-- SHA256 {hashlib.sha256(data).hexdigest()} -->','','Hyprune owns `~/.config/hyprune/input.json`. Edit it directly or use the Director’s Settings tab. Core validates and live-reloads it independently of Hyprland. Each action accepts up to three bindings. `[L]` means hold for **'+str(config['longHoldMs'])+' ms** by default.','','Movement keys are listed **HJKL first**, then WASD and arrows. E uses a window or workspace wall in place. F zooms into that window or workspace. From world control, Super+Tab or Back enters a real free cursor (an active carry finishes first). The camera freezes; layers and other outputs receive ordinary input. From use/focus, Back or Super+Tab returns directly to the world. From the world it enters free cursor; another press returns to the world. A colliding Hyprland shortcut is stolen only in the mode that defines it, while the world is active.','','Q holds scope zoom; the wheel changes its magnification. Ctrl sprints and Shift crouches (descends in flight), as in most first-person games. Ctrl, the sprint key, also snaps position-tool movement to 0.1 m, rotation to 15°, and scale factors to 0.1; holding it never moves the camera. Keys 1–4 select tools; 5 selects the Placement tool; 9 selects the debug tool. Wheel selects an unplaced window; LMB places ahead and RMB places on a surface. MMB pockets the aimed window for travel. A nonempty queue preselects tool 5 on first entry. HUD concepts (Adventure, Instrument and Minimal) are selected in Settings → Appearance, with Adventure as default. The window tool cycles place/lock; the path tool cycles line/curve/arc and Alternate toggles open/closed; the position tool cycles move/rotate/scale.','']
order=['look','forward','back','left','right','menu','markers.reveal','sprint','up','down','use','focus','noclip','scope','debug','capture','record.toggle','carry','resize','distance','rotate','carry.facing','content.scale','window.reset','tool1','tool2','tool3','tool4','tool5','tool9','hud.cycle','transport','autopilot','primary','secondary','alternate','cycle','wheel','fly','exit']
world=config['modes']['world']
lines += ['Super+LMB on a window’s edge (about 10 cm) resizes it from the nearest corner; anywhere else it carries. The Super window gestures (carry, resize, push/pull, rotate, content scale) also work while using a window (E). A window brought into the world (opened there, moved or dragged in from another output, pulled, recalled, placed or carried off its wall) becomes a floating window at its own size (very large ones are scaled down); back on its home wall it is tiled again.','']
lines += ['Carrying: `'+(' / '.join(world.get('carry.facing',[])) or 'Unbound')+'` toggles **FACING YOU / KEEP ANGLE**. `'+(' / '.join(world['rotate']))+'` rotates; `'+(' / '.join(world.get('content.scale',[])) or 'Unbound')+'` changes content scale. `'+(' / '.join(world.get('window.reset',[])) or 'Unbound')+'` resets the window. The shell reports content scale and client pixel dimensions.','']
lines += ['## Tool input slots', '', 'Primary, Secondary, Alternate and Cycle use the same globally rebindable `primary`, `secondary`, `alternate`, `cycle` actions in every tool. Their defaults are LMB, RMB, MMB and Wheel. Unassigned slots do nothing. Super modifier gestures always override tool slots, including during a carry.', '', '| Tool | Primary | Secondary | Alternate | Cycle |', '| --- | --- | --- | --- | --- |', '| Normal | Click / interact | Right-click | Middle-click | Scroll window |', '| Window | Tag/mount or lock (sub-mode) | Lock/unlock | Unassigned | Place/lock sub-mode |', '| Path | Add point; drag a point; click a segment to insert | Remove the aimed point (else the last) | Open/close path | Line/curve/arc |', '| Position | Select / drag gizmo | World/local axes | Toggle snapping | Move/rotate/scale |', '| Placement | Place ahead | Mount on surface | Pocket aimed window | Select pocketed window |', '| Debug (9) | Inspect the aimed item | Close the info card | Unassigned | Next/previous debug layer |', '', 'Paths show only in the path tool, with their points and curve handles; the point under the reticle highlights. Press on a point and drag to move it (Ctrl snaps to 0.1 m), release to commit; Escape cancels the drag. Ctrl+Z and Ctrl+Shift+Z (or Ctrl+Y) undo and redo path edits as they do position edits. Period (`.`) in the path tool keeps all paths shown in the other tools; the debug view (F3) shows them too.', '', '## Debug tool', '', 'Key 9 selects the **debug tool**. It shows one debug layer at a time; the wheel (Cycle) steps through them and a banner at the top names the layer with a one-line legend of its colours. The layers are: window boxes and mounts (window volumes, workspace wall, tool mount and data object frames); window zones (where windows are placed freely and objects are refused); collision (floors, walls, invisible walls or backstops, object proxies) near you; playable volumes and the fly ceiling; paths with their points and stops, and the walking graph; keepClear volumes, screen approach zones and spawn or climb clearances; seats with their approach; visibility regions (where you are, what is drawn from there); character steering (body, predicted positions, offset from the route, detours, who holds whom up); and every volume the placement rules refuse, by rule.', '', 'Primary on something in the current layer opens an info card: its id, type, owner and area, and whether it blocks placement and why (for example **Inside a window zone**). In the placement layer, Primary on open ground says whether a 0.5 m box would be allowed there. Secondary closes the card. The tool draws thick lines (3 px at 1080p, scaled with the output) and light fills, dimmed and dashed behind walls; the F3 debug view keeps its thin lines. A still view renders no frames while the tool is out.', '', 'Tool hints come from core declarations over IPC. Pocketed windows remain alive but invisible; newest pocketed comes first. There is no return-to-last-spot command. `windows.carry_face_player` defaults to true in Lua config; content scale changes client logical resolution while keeping the world rectangle fixed. Reset returns content resolution, facing and distance to defaults, subject to collision recovery.', '']
for mode,actions in config['modes'].items():
 lines+=['## '+{'world':'In-world','interactive':'Interactive / use in place','focus':'Focus / fullscreen','menu':'Menu'}[mode],'','| Action | Default bindings |','| --- | --- |']
 for action in order:
  if action in actions:lines.append('| '+action+' | '+(', '.join('`'+b.replace('|','\\|')+'`'for b in actions[action]) or 'Unbound')+' |')
 lines+=['']
lines+=['A short **Tab** tap is `markers.reveal`: markers for the tracked quest step, the waypoint, area homes and places nearby fade in for about 4 s (Settings → Guidance). Holding Tab is `menu`: the hold ring appears after a short delay and the Director opens; a tap never opens it. A plain and a `[L]` binding of the same key in one mode for different actions form such a tap/hold pair; any other duplicate is a conflict.','','**Ctrl+R** (`record.toggle`, world mode only: in apps Ctrl+R stays theirs) starts and stops a private debug recording of input, camera and frame timing for measuring motion feel. A red REC dot and the elapsed time show while it runs; on stop the HUD asks for an optional label (Esc skips). Recording does not change how motion runs. Application keystrokes are masked unless explicitly enabled through the recording API.','','## File options','','| Option | Default | Valid range / meaning |','| --- | --- | --- |','| version | '+str(config['version']).lower()+' | Exactly 3. A version 2 file is upgraded once: sprint, down and record.toggle take the new defaults only where they still had the old ones (Shift_L, Control_L, unbound) and the new key is free |','| longHoldMs | '+str(config['longHoldMs']).lower()+' | 100–5000 ms |','| scopeVignette | '+str(config['scopeVignette']).lower()+' | Scope ring and shaded edges |','| invert_y | '+str(config['invert_y']).lower()+' | Reverse vertical mouse look; false means mouse up looks up |','| show_area_markers | '+str(config.get('show_area_markers',False)).lower()+' | Optional core-rendered area/place labels; active waypoint/route remain visible |','| useDistance | '+str(config['useDistance']).lower()+' | 0.2–30 m; E maximum distance |','| useTolerance | '+str(config['useTolerance']).lower()+' | 0–0.5 m margin around an aimed surface |','| captureInputLimit | '+str(config['captureInputLimit']).lower()+' | 16–1024 recent input events in captures |','| modes | tables above | All listed actions; 0–3 bindings each |','','Binding names use XKB keysyms, `Super+Shift+Ctrl+Alt+key`, `LMB`, `RMB`, `MMB`, `Back`, `Forward`, `ButtonN`, `Wheel`, `WheelUp`, `WheelDown`, or `MouseMove`. Keys use the active keyboard layout’s base-level symbol, with letters canonicalized to lowercase; Shift/Ctrl/Alt/Super are separate modifiers. Press identity is retained through release even if modifiers or layout change. Modifier order is canonicalized. F12 remains the emergency exit outside free-cursor mode. In free-cursor mode Back and Super+Tab return to world control; Escape does too when no app has keyboard focus. Other keys go to native focus. Internal conflicts reject a save; Hyprland collisions are reported and accepted. Invalid edits retain the last valid configuration.','','U in world, or Super+U in interactive/focus/menu, writes a private timestamped JSON/PNG capture pair under `$XDG_STATE_HOME/hyprune/captures/` (default `~/.local/state/hyprune/captures/`) and shows the path in a notice. The JSON records the completed world frame camera, age and timings, plus mode, tools, surfaces, placements, recent IPC/events and the bounded input history.','','Compositor graphics, sensitivity and inertia remain in `hl.plugin.hyprune.config({...})`; input bindings belong in the independent JSON file. Walking and running speed, view bob, the reticle and reach limits are [player settings](#player-settings).','','Tools save paths, window locks and object transforms in `$XDG_STATE_HOME/hyprune/editor.json`, scoped by world and area. Authored world packages stay read-only.','']
lines+=['## Player settings','','Movement speed, view bob, the reticle and how far your hands reach are player settings. Change them in the Director’s Settings tab or with `player.set` (IPC 0.19); changes apply immediately. Only changed keys are saved, to `$HYPRUNE_PLAYER_FILE`, else `$XDG_CONFIG_HOME/hyprune/player.json` (default `~/.config/hyprune/player.json`). `hl.plugin.hyprune.config({player = {...}})` accepts the same keys; saved values win. The old `player.run_multiplier` still works in Lua and sets run speed to walk speed × multiplier.','','| Setting | Default | Valid range / meaning |','| --- | --- | --- |','| walk_speed | 4.0 | 0.5–20 m/s; walking and the flight base speed |','| run_speed | 10.0 | 0.5–30 m/s while `sprint` is held; flight scales by run/walk |','| view_bob | subtle | off, subtle or normal walking view bob |','| reticle_style | cross_dot | cross_dot, t_dot, circle_dot, dot, cross or chevron |','| reticle_size | 18 | 6–64 px, full extent |','| reticle_thickness | 2 | 1–6 px |','| reticle_gap | 4 | 0–20 px from the centre to the arms |','| reticle_opacity | 0.9 | 0.2–1 |','| reticle_outline | true | Dark 1 px outline for contrast |','| reticle_colour | theme | `theme` (the HUD theme) or an RGB colour |','| reticle_dynamic | true | The reticle opens up while you move or turn |','| reach_grab | 15 | 1–100 m; Super+button window gestures (carry, resize) |','| reach_mount | 8 | 1–100 m; snapping into tool-mount frames (tools 2 and 5, releasing a carry) |','| reach_placement | 12 | 1–100 m; placing on a surface and pocketing (tool 5), mounting on a wall (tool 2), path points (tool 3) |','','The graphics `reduced_motion` setting turns off the view bob and the dynamic reticle whatever these settings say. Clicking into a window with the normal tool has no reach limit; beyond the other limits the action is refused and a notice says how far away the target is.','','The reticle shows what the current tool or held Super gesture would do: a valid target gets corner brackets in the valid colour, a target out of reach turns the reticle to the warning colour with a hollow centre and a **Too far: N m** label (a refused action also flashes it), a target that can\'t take the action turns the reticle into an x in the warning colour, and carrying a window shows brackets in the reticle colour. Shape changes go with every colour change, so no state relies on colour alone. The reticle is hidden in the free cursor and follows the pointer while typing.','']
lines+=['## Workspaces','','Entering the world switches the output to the free room, native workspace **20** (`windows.world_workspace`). Each area of the loaded world has a default home at `windows.workspace_base` (**20**) + its slot: slot 01 is workspace 21, slot 02 is 22, and so on. Any Hyprland workspace bind or the Director switching to a home travels to that area, and windows on it appear on the area\'s main wall. Your own Lua config values and explicit `workspace.bind` homes win over these defaults.','']
output=root/'src/content/docs/keymap.md';text='\n'.join(lines)
if args.check:
 if not output.exists() or output.read_text()!=text:raise SystemExit('Keymap page is stale; run scripts/generate-keymap.py')
else:output.write_text(text)
